import{Q as e,V as t,ht as n,it as r,nt as i,rt as a,tt as o,yt as s}from"./chunks/framework.K9m71cl2.js";var c=JSON.parse(`{"title":"教程篇-如何挂起/暂停学生端进程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/suspend_student.md","filePath":"guide/suspend_student.md","lastUpdated":0}`),l={name:`guide/suspend_student.md`};function u(t,c,l,u,d,f){let p=s(`ArticleMetadata`);return n(),o(`div`,null,[c[0]||=e(`h1`,{id:`教程篇-如何挂起-暂停学生端进程`,tabindex:`-1`},[a(`教程篇-如何挂起/暂停学生端进程 `),e(`a`,{class:`header-anchor`,href:`#教程篇-如何挂起-暂停学生端进程`,"aria-label":`Permalink to “教程篇-如何挂起/暂停学生端进程”`},`​`)],-1),r(p,{"file-time":`2026-08-02T03:48:06.000Z`}),c[1]||=i(`<blockquote><p>前言：<strong>挂起/暂停学生端进程</strong> 可以让教师端对学生端的监控的画面停止更新，可方便同学们 <strong>“自主学习”</strong>，防止牢逝通过教师端的监控画面看到。 与直接 <strong>结束学生端进程</strong> 不同，仅 <strong>挂起/暂停学生端进程</strong> 只会让教师端对学生端的监控的画面停止更新，而不会显示为掉线。相反，直接结束 <strong>结束学生端进程</strong> 会在教师端显示为该学生端掉线，容易被牢逝察觉，导致被制裁。</p></blockquote><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to “适用场景”">​</a></h2><ul><li>想要自主学习，但是担心被牢逝发现</li><li>想了解相关原理</li></ul><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to “操作步骤”">​</a></h2><h3 id="一-打开-任务管理器" tabindex="-1">一：打开 <code>任务管理器</code> <a class="header-anchor" href="#一-打开-任务管理器" aria-label="Permalink to “一：打开 任务管理器”">​</a></h3><div class="info custom-block"><p class="custom-block-title">一：打开 <code>任务管理器</code></p><p><strong>操作示例：</strong></p><ol><li>在任务栏空白位置单击鼠标右键，点击 <strong>打开任务管理器(K)</strong></li><li>在弹出的窗口中点击左下角的 <strong>详细信息</strong></li></ol></div><h3 id="二-打开-资源监视器" tabindex="-1">二：打开 <code>资源监视器</code> <a class="header-anchor" href="#二-打开-资源监视器" aria-label="Permalink to “二：打开 资源监视器”">​</a></h3><div class="info custom-block"><p class="custom-block-title">二：打开 <code>资源监视器</code></p><p><strong>操作示例：</strong></p><ol><li>任务管理器默认选项开为 <strong>进程</strong>，请在顶栏切换到性能选项卡</li><li>点击底部的 <strong>打开资源监视器</strong></li><li>点击 <code>名称</code> 二字，切换到名称排序（<em>由于列表的默认排序方式为状态，但部分程序的状态在改变，导致列表变化很快，不易精准找到 <code>Student.exe</code>，因此建议点击名称以切换到名称排序</em>）</li></ol></div><h3 id="三-暂停-student-exe-进程" tabindex="-1">三：暂停 <code>Student.exe</code> 进程 <a class="header-anchor" href="#三-暂停-student-exe-进程" aria-label="Permalink to “三：暂停 Student.exe 进程”">​</a></h3><div class="info custom-block"><p class="custom-block-title">三：暂停 <code>Student.exe</code> 进程</p><ol><li>往下拉找到名为 <code>Student.exe</code> 的进程</li><li>右键单击该进程，在弹出的菜单里选择 <code>暂停进程(S)</code></li></ol></div>`,10)])}var d=t(l,[[`render`,u]]);export{c as __pageData,d as default};